#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;

cpp_int power(cpp_int base, long long exponent) {
    cpp_int result = 1;
    while (exponent > 0) {
        if (exponent & 1LL) result *= base;
        exponent >>= 1LL;
        if (exponent > 0) base *= base;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    cpp_int sum = 1;
    cpp_int combination = 1;

    for (long long i = 1; i <= k; ++i) {
        combination *= n - i + 1;
        combination /= i;

        if (i >= 2) {
            sum += combination * power(cpp_int(i - 1), i - 2);
        }
    }

    cout << sum << '\n';
    return 0;
}

#include <iostream>
#include <algorithm>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;

cpp_int binomial(long long n, long long k) {
    if (k < 0 || k > n) return 0;

    k = min(k, n - k);
    cpp_int result = 1;

    for (long long i = 1; i <= k; ++i) {
        result *= n - k + i;
        result /= i;
    }

    return result;
}

cpp_int power(cpp_int base, long long exponent) {
    cpp_int result = 1;

    while (exponent > 0) {
        if (exponent & 1LL) result *= base;
        exponent >>= 1LL;
        if (exponent > 0) base *= base;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    cpp_int sum = 1;

    if (k >= 2 && k <= n) {
        cpp_int combination = binomial(n, k);

        for (long long current = k; current >= 2; --current) {
            sum += combination * power(cpp_int(current - 1), current - 2);

            if (current > 2) {
                combination *= current;
                combination /= n - current + 1;
            }
        }
    }

    cout << sum << '\n';
    return 0;
}

